mdl = 'cfgDemo';
new_system(mdl); load_system(mdl);
add_block('simulink/Sources/Sine Wave',       [mdl '/Sine'], 'Position',[40 40 70 70]);
add_block('simulink/Continuous/Integrator',   [mdl '/Int'],  'Position',[140 40 170 70]);
add_block('simulink/Sinks/Out1',              [mdl '/y'],    'Position',[240 45 270 65]);
add_line(mdl,'Sine/1','Int/1','autorouting','on');
add_line(mdl,'Int/1','y/1','autorouting','on');

set_param(mdl, 'SolverType','Variable-step', 'Solver','ode15s', ...
               'StartTime','0', 'StopTime','40', 'RelTol','1e-6');
cs = getActiveConfigSet(mdl);
fprintf('%s / %s / stop=%s\n', get_param(mdl,'SolverType'), ...
        get_param(mdl,'Solver'), get_param(mdl,'StopTime'));
out = sim(mdl);
close_system(mdl,0);

mdl = 'solverDemo';
new_system(mdl); load_system(mdl);
add_block('simulink/Sources/Step',          [mdl '/u'],  'Position',[40 40 70 70]);
add_block('simulink/Continuous/Transfer Fcn',[mdl '/G'], 'Position',[140 40 200 80]);
add_block('simulink/Sinks/Out1',            [mdl '/y'],  'Position',[260 45 290 65]);
set_param([mdl '/G'],'Denominator','[1 2 1]');
add_line(mdl,'u/1','G/1','autorouting','on');
add_line(mdl,'G/1','y/1','autorouting','on');

% stiff solver, tight tolerance, capped step
set_param(mdl,'SolverType','Variable-step','Solver','ode15s', ...
              'RelTol','1e-6','AbsTol','1e-8','MaxStep','0.01','StopTime','10');
out1 = sim(mdl);

% fixed-step, as required for code generation
set_param(mdl,'SolverType','Fixed-step','Solver','ode3','FixedStep','1e-3');
out2 = sim(mdl);
close_system(mdl,0);

mdl = 'zcDemo';
new_system(mdl); load_system(mdl);
add_block('simulink/Sources/Sine Wave',        [mdl '/u'],   'Position',[40 40 70 70]);
add_block('simulink/Discontinuities/Saturation',[mdl '/Sat'],'Position',[140 40 170 70]);
add_block('simulink/Sinks/Out1',               [mdl '/y'],   'Position',[240 45 270 65]);
add_line(mdl,'u/1','Sat/1','autorouting','on');
add_line(mdl,'Sat/1','y/1','autorouting','on');

set_param(mdl,'SolverType','Variable-step','Solver','ode23t', ...
              'ZeroCrossControl','UseLocalSettings', ...
              'ZeroCrossAlgorithm','Adaptive', ...
              'MaxConsecutiveZCs','1000','StopTime','10');
out = sim(mdl);

% disable zero-crossing detection on one block only
set_param([mdl '/Sat'],'ZeroCross','off');
close_system(mdl,0);

mdl = 'ioDemo';
new_system(mdl); load_system(mdl);
add_block('simulink/Sources/In1',        [mdl '/u'],   'Position',[40 45 70 65]);
add_block('simulink/Continuous/Integrator',[mdl '/Int'],'Position',[140 40 170 70]);
add_block('simulink/Sinks/Out1',         [mdl '/y'],   'Position',[240 45 270 65]);
add_line(mdl,'u/1','Int/1','autorouting','on');
add_line(mdl,'Int/1','y/1','autorouting','on');

% mark the integrator output for logging so that logsout is populated
ph = get_param([mdl '/Int'],'PortHandles');
set_param(ph.Outport(1),'DataLogging','on', ...
          'DataLoggingNameMode','Custom','DataLoggingName','xInt');

t = (0:0.001:5)';  u = sin(2*pi*3*t);
assignin('base','t',t); assignin('base','u',u);
set_param(mdl,'LoadExternalInput','on','ExternalInput','[t, u]', ...
              'SaveOutput','on','SaveState','on','SaveFormat','Dataset', ...
              'SignalLogging','on','SignalLoggingName','logsout', ...
              'StopTime','5');
out = sim(mdl);
y  = out.yout{1}.Values;      % Dataset element -> timeseries
ls = out.logsout;             % Simulink.SimulationData.Dataset
plot(y.Time, y.Data); grid on
close_system(mdl,0);

out = sim('myModel');
ds  = out.logsout;
fprintf('%d logged signals\n', ds.numElements);
sig = ds.get('speed');            % Simulink.SimulationData.Signal
ts  = sig.Values;                 % timeseries
plot(ts.Time, ts.Data); grid on

% build stimulus for a later run
in  = Simulink.SimulationData.Dataset;
in  = addElement(in, timeseries(sin(0:0.01:10)', (0:0.01:10)'), 'u');
simIn = Simulink.SimulationInput('myModel');
simIn = simIn.setExternalInput(in);
out2  = sim(simIn);

t = (0:0.01:10)';
meas = timeseries(sin(t) + 0.02*randn(size(t)), t, 'Name','measured');
refID = Simulink.sdi.createRun('Bench measurement', 'namevalue', ...
                               {'speed'}, {meas});

out   = sim('myModel');
simID = Simulink.sdi.createRun('Model v3', 'namevalue', ...
                               {'speed'}, {out.logsout.get('speed').Values});
Simulink.sdi.view

baseID = Simulink.sdi.createRun('baseline','file','baseline.mat');
out    = sim('myModel');
newID  = Simulink.sdi.getCurrentSimulationRun('myModel');

dr = Simulink.sdi.compareRuns(baseID, newID, 'abstol', 1e-4, 'reltol', 1e-3, ...
                              'align', Simulink.sdi.AlignType.SignalName);
fprintf('overall: %s\n', string(dr.Status));
for k = 1:dr.Count
    r = dr.getResultByIndex(k);
    fprintf('%-20s %-8s max diff %g\n', r.Name, string(r.Status), r.MaxDifference);
end
Simulink.sdi.view

Simulink.sdi.clear;
for Kp = [1 2 5]
    assignin('base','Kp',Kp);
    out = sim('myModel');
    rid = Simulink.sdi.getCurrentSimulationRun('myModel');
    r = Simulink.sdi.getRun(rid);
    r.Name = sprintf('Kp = %g', Kp);
end
Simulink.sdi.view

mdl = 'sldemo_fuelsys';
load_system(mdl);
modeladvisor(mdl);

sysList = {'sldemo_fuelsys'};
checks  = {'mathworks.design.UnconnectedLinesPorts', ...
           'mathworks.design.OptimizeBlocksForCodeGen'};
results = ModelAdvisor.run(sysList, checks, 'DisplayResults','Summary');
r = results{1};
fprintf('pass=%d warn=%d fail=%d\n', r.NumPass, r.NumWarn, r.NumFail);
if r.NumFail > 0
    error('Model Advisor reported %d failures', r.NumFail);
end

