mdl = 'varDemo';
new_system(mdl); load_system(mdl);
add_block('simulink/Sources/In1',        [mdl '/u'], 'Position',[40 45 70 65]);
add_block('simulink/Math Operations/Gain',[mdl '/K'], 'Position',[140 40 170 70]);
add_block('simulink/Sinks/Out1',         [mdl '/y'], 'Position',[240 45 270 65]);
