for k = 1:numel(vars)
    fprintf('%-20s from %-16s used by %d block(s)\n', ...
        vars(k).Name, vars(k).SourceType, numel(vars(k).Users));
end

unused = Simulink.findVars(mdl, 'FindUsedVars', false);
fprintf('%d unused variables\n', numel(unused));
close_system(mdl,0);

mdl = 'depDemo';
new_system(mdl);
add_block('simulink/Sources/Sine Wave',[mdl '/u'], 'Position',[40 40 70 70]);
add_block('simulink/Sinks/Out1',       [mdl '/y'], 'Position',[160 45 190 65]);
add_line(mdl,'u/1','y/1','autorouting','on');
