mdl = 'cmdDemo';
new_system(mdl); load_system(mdl);
add_block('simulink/Sources/Sine Wave',    [mdl '/u'],   'Position',[40 40 70 70]);
add_block('simulink/Continuous/Integrator',[mdl '/Int'], 'Position',[140 40 170 70]);
add_block('simulink/Sinks/Out1',           [mdl '/y'],   'Position',[240 45 270 65]);
add_line(mdl,'u/1','Int/1','autorouting','on');
add_line(mdl,'Int/1','y/1','autorouting','on');

set_param(mdl,'SimulationCommand','update');     % compile-only check
set_param(mdl,'StopTime','60');
set_param(mdl,'SimulationCommand','start');

% the command is QUEUED - wait for the status to actually change
for k = 1:50
    if ~strcmp(get_param(mdl,'SimulationStatus'),'stopped'), break; end
    pause(0.1);
end

% ALWAYS bound the poll loop - never spin on status alone
for k = 1:100
    if strcmp(get_param(mdl,'SimulationStatus'),'stopped'), break; end
    set_param(mdl,'SimulationCommand','pause');
    pause(0.1);
    tNow = get_param(mdl,'SimulationTime');
    fprintf('t = %g\n', tNow);
    if tNow > 10
        break;
    end
    set_param(mdl,'SimulationCommand','continue');
    pause(0.1);
end

set_param(mdl,'SimulationCommand','stop');
pause(0.5);
close_system(mdl,0);
